 maintainability by centralizing model configuration and aligning with environment-driven settings.","tree":{"sha":"c0978d44841f4528c4c12ccd941637ce44b55be7","url":"https://api.github.com/repos/VamshiS123/Sprout/git/trees/c0978d44841f4528c4c12ccd941637ce44b55be7"},"url":"https://api.github.com/repos/VamshiS123/Sprout/git/commits/ad99e637b329485502bbe2974dba22cb04a6462f","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/63719951?v=4","events_url":"https://api.github.com/users/Harikeshav-R/events{/privacy}","followers_url":"https://api.github.com/users/Harikeshav-R/followers","following_url":"https://api.github.com/users/Harikeshav-R/following{/other_user}","gists_url":"https://api.github.com/users/Harikeshav-R/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/Harikeshav-R","id":63719951,"login":"Harikeshav-R","node_id":"MDQ6VXNlcjYzNzE5OTUx","organizations_url":"https://api.github.com/users/Harikeshav-R/orgs","received_events_url":"https://api.github.com/users/Harikeshav-R/received_events","repos_url":"https://api.github.com/users/Harikeshav-R/repos","site_admin":false,"starred_url":"https://api.github.com/users/Harikeshav-R/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/Harikeshav-R/subscriptions","type":"User","url":"https://api.github.com/users/Harikeshav-R","user_view_type":"public"},"html_url":"https://github.com/VamshiS123/Sprout/commit/ad99e637b329485502bbe2974dba22cb04a6462f","node_id":"C_kwDOThZHUdoAKGFkOTllNjM3YjMyOTQ4NTUwMmJiZTI5NzRkYmEyMmNiMDRhNjQ2MmY","parents":[{"html_url":"https://github.com/VamshiS123/Sprout/commit/d6d2c60f94840a0ba37e96605a4f54283022be15","sha":"d6d2c60f94840a0ba37e96605a4f54283022be15","url":"https://api.github.com/repos/VamshiS123/Sprout/commits/d6d2c60f94840a0ba37e96605a4f54283022be15"}],"sha":"ad99e637b329485502bbe2974dba22cb04a6462f","url":"https://api.github.com/rep