 all tools by centralizing endpoint and configuration management.","tree":{"sha":"961a0f4fe36307e5b490d80c27480cc9c1839a35","url":"https://api.github.com/repos/VamshiS123/Sprout/git/trees/961a0f4fe36307e5b490d80c27480cc9c1839a35"},"url":"https://api.github.com/repos/VamshiS123/Sprout/git/commits/ec5c70ae319f7685726b915582d25e16e49619a2","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/63719951?v=4","events_url":"https://api.github.com/users/Harikeshav-R/events{/privacy}","followers_url":"https://api.github.com/users/Harikeshav-R/followers","following_url":"https://api.github.com/users/Harikeshav-R/following{/other_user}","gists_url":"https://api.github.com/users/Harikeshav-R/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/Harikeshav-R","id":63719951,"login":"Harikeshav-R","node_id":"MDQ6VXNlcjYzNzE5OTUx","organizations_url":"https://api.github.com/users/Harikeshav-R/orgs","received_events_url":"https://api.github.com/users/Harikeshav-R/received_events","repos_url":"https://api.github.com/users/Harikeshav-R/repos","site_admin":false,"starred_url":"https://api.github.com/users/Harikeshav-R/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/Harikeshav-R/subscriptions","type":"User","url":"https://api.github.com/users/Harikeshav-R","user_view_type":"public"},"html_url":"https://github.com/VamshiS123/Sprout/commit/ec5c70ae319f7685726b915582d25e16e49619a2","node_id":"C_kwDOThZHUdoAKGVjNWM3MGFlMzE5Zjc2ODU3MjZiOTE1NTgyZDI1ZTE2ZTQ5NjE5YTI","parents":[{"html_url":"https://github.com/VamshiS123/Sprout/commit/5604f51645754933e364fb7add476f4ed422c7ca","sha":"5604f51645754933e364fb7add476f4ed422c7ca","url":"https://api.github.com/repos/VamshiS123/Sprout/commits/5604f51645754933e364fb7add476f4ed422c7ca"}],"sha":"ec5c70ae319f7685726b915582d25e16e49619a2","url":"https://api.github.com/repos/VamshiS123/Sprout/commits/ec5c7