ent` for improved flexibility.","tree":{"sha":"7cb56530b5a6381150e41cb2a856d6f59c3cc09e","url":"https://api.github.com/repos/VamshiS123/Sprout/git/trees/7cb56530b5a6381150e41cb2a856d6f59c3cc09e"},"url":"https://api.github.com/repos/VamshiS123/Sprout/git/commits/0c27ab1a9d1061e121e5a479a1d0397bd099b143","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/63719951?v=4","events_url":"https://api.github.com/users/Harikeshav-R/events{/privacy}","followers_url":"https://api.github.com/users/Harikeshav-R/followers","following_url":"https://api.github.com/users/Harikeshav-R/following{/other_user}","gists_url":"https://api.github.com/users/Harikeshav-R/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/Harikeshav-R","id":63719951,"login":"Harikeshav-R","node_id":"MDQ6VXNlcjYzNzE5OTUx","organizations_url":"https://api.github.com/users/Harikeshav-R/orgs","received_events_url":"https://api.github.com/users/Harikeshav-R/received_events","repos_url":"https://api.github.com/users/Harikeshav-R/repos","site_admin":false,"starred_url":"https://api.github.com/users/Harikeshav-R/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/Harikeshav-R/subscriptions","type":"User","url":"https://api.github.com/users/Harikeshav-R","user_view_type":"public"},"html_url":"https://github.com/VamshiS123/Sprout/commit/0c27ab1a9d1061e121e5a479a1d0397bd099b143","node_id":"C_kwDOThZHUdoAKDBjMjdhYjFhOWQxMDYxZTEyMWU1YTQ3OWExZDAzOTdiZDA5OWIxNDM","parents":[{"html_url":"https://github.com/VamshiS123/Sprout/commit/eea7c26e98136d74e578818b68b16d9a14a04666","sha":"eea7c26e98136d74e578818b68b16d9a14a04666","url":"https://api.github.com/repos/VamshiS123/Sprout/commits/eea7c26e98136d74e578818b68b16d9a14a04666"}],"sha":"0c27ab1a9d1061e121e5a479a1d0397bd099b143","url":"https://api.github.com/repos/VamshiS123/Sprout/commits/0c27ab1a9d1061e121e5a479a1d0397bd099b143